/* ---------- pick a language and lay it over the English ---------- */
const LANG = (() => {
  const ok = (l) => l && LANGS.some(([k]) => k === l) ? l : null;
  try { const q = new URLSearchParams(location.search).get('lang'); if (ok(q)) { try { localStorage.setItem('stand-lang', q); } catch {} return q; } } catch {}
  try { const s = ok(localStorage.getItem('stand-lang')); if (s) return s; } catch {}
  for (const l of (navigator.languages || [navigator.language || 'en'])) { const k = ok(String(l).slice(0, 2).toLowerCase()); if (k) return k; }
  return 'en';
})();
const U = Object.assign({}, UI.en, UI[LANG] || {});
const fmt = (s, o) => String(s).replace(/\{(\w+)\}/g, (m, k) => (k in o ? o[k] : m));
(() => {
  const t = TR[LANG];
  if (t) {
    F.forEach((f) => {
      const x = t.f[f.id]; if (x) { f.title = x[0]; f.lead = x[1]; if (f.short || x[2]) f.short = x[2] || x[0]; }
      f.ch.forEach((c) => {
        const y = t.c[c.id]; if (!y) return;
        [c.name, c.h, c.p] = y;
        if (y[3]) { if (c.grid) c.grid = y[3]; else if (c.steps) c.steps = y[3]; else if (c.chips) c.chips = y[3]; }
      });
    });
    if (t.uniq) UNIQ.forEach((u, i) => { if (t.uniq[i]) { u[3] = t.uniq[i][0]; u[4] = t.uniq[i][1]; } });
    ALSO.forEach((a, i) => { if (t.also[i]) a[1] = t.also[i]; });
    HIGH.forEach((h, i) => { const y = t.high[i]; if (y) { h.h = y[0]; h.p = y[1]; } });
    TOOLS.forEach((a, i) => { if (t.tools[i]) a[1] = t.tools[i]; });
    t.faq.forEach((q, i) => { FAQ[i] = q; });
  }
  HIGH.forEach((h) => { const f = F.find((x) => x.id === h.to[0]); if (f) h.k = f.title; });
  document.documentElement.lang = LANG === 'pt' ? 'pt-PT' : LANG;
  document.title = U.title;
})();

/* ---------- the words in the page around the folders, and the language picker ---------- */
(() => {
  const $ = (id) => document.getElementById(id);
  const set = (id, t) => { const e = $(id); if (e) e.textContent = t; };
  set('topNote', U.top); set('footP', U.foot); set('lkPriv', U.privacy); set('lkTerms', U.terms); set('lkSupport', U.support); set('legalNote', U.legal);
  const al = (id, t) => { const e = $(id); if (e) e.setAttribute('aria-label', t); };
  al('drawer', U.drawerLabel); al('also', U.alsoLabel); al('prevBtn', U.prev); al('nextBtn', U.next); al('closeBtn', U.close);
  const sel = $('langSel'); if (!sel) return;
  sel.innerHTML = LANGS.map(([k, n]) => `<option value="${k}" lang="${k}"${k === LANG ? ' selected' : ''}>${n}</option>`).join('');
  sel.setAttribute('aria-label', U.lang);
  sel.addEventListener('change', () => {
    try { localStorage.setItem('stand-lang', sel.value); } catch {}
    try { const u = new URL(location.href); u.searchParams.set('lang', sel.value); location.replace(u.href); } catch { location.reload(); }
  });
})();
